import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused SiLU-multiply kernel
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Fused SiLU(gate) * up kernel
__global__ void fused_silu_mul_kernel(
    const float* __restrict__ gate,
    const float* __restrict__ up,
    float* __restrict__ out,
    int size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float g = gate[idx];
        float sigmoid_g = 1.0f / (1.0f + expf(-g));
        float silu_g = g * sigmoid_g;
        out[idx] = silu_g * up[idx];
    }
}

// Fused weighted sum kernel for expert outputs
// expert_out: (num_tokens, top_k, hidden_size)
// weights: (num_tokens, top_k)
// out: (num_tokens, hidden_size)
__global__ void fused_weighted_sum_kernel(
    const float* __restrict__ expert_out,
    const float* __restrict__ weights,
    float* __restrict__ out,
    int num_tokens,
    int top_k,
    int hidden_size
) {
    int token_idx = blockIdx.x;
    int hidden_idx = blockIdx.y * blockDim.x + threadIdx.x;

    if (token_idx < num_tokens && hidden_idx < hidden_size) {
        float sum = 0.0f;
        for (int k = 0; k < top_k; k++) {
            float w = weights[token_idx * top_k + k];
            float v = expert_out[token_idx * top_k * hidden_size + k * hidden_size + hidden_idx];
            sum += w * v;
        }
        out[token_idx * hidden_size + hidden_idx] = sum;
    }
}

torch::Tensor fused_silu_mul_hip(torch::Tensor gate, torch::Tensor up) {
    auto size = gate.numel();
    auto out = torch::empty_like(gate);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_silu_mul_kernel<<<num_blocks, block_size>>>(
        gate.data_ptr<float>(),
        up.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}

torch::Tensor fused_weighted_sum_hip(torch::Tensor expert_out, torch::Tensor weights) {
    // expert_out: (num_tokens, top_k, hidden_size)
    // weights: (num_tokens, top_k)
    int num_tokens = expert_out.size(0);
    int top_k = expert_out.size(1);
    int hidden_size = expert_out.size(2);

    auto out = torch::empty({num_tokens, hidden_size}, expert_out.options());

    const int block_size = 256;
    dim3 grid(num_tokens, (hidden_size + block_size - 1) / block_size);

    fused_weighted_sum_kernel<<<grid, block_size>>>(
        expert_out.data_ptr<float>(),
        weights.data_ptr<float>(),
        out.data_ptr<float>(),
        num_tokens,
        top_k,
        hidden_size
    );

    return out;
}
"""

cpp_source = """
torch::Tensor fused_silu_mul_hip(torch::Tensor gate, torch::Tensor up);
torch::Tensor fused_weighted_sum_hip(torch::Tensor expert_out, torch::Tensor weights);
"""

fused_ops = load_inline(
    name="fused_moe_ops",
    cpp_sources=cpp_source,
    cuda_sources=hip_source,
    functions=["fused_silu_mul_hip", "fused_weighted_sum_hip"],
    verbose=True,
    extra_cuda_cflags=["-O3"],
)


class MoEGate(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        routed_scaling_factor: float = 1.0,
        norm_topk_prob: bool = True,
    ):
        super().__init__()
        self.top_k = num_experts_per_tok
        self.n_routed_experts = n_routed_experts
        self.n_group = n_group
        self.topk_group = topk_group
        self.routed_scaling_factor = routed_scaling_factor
        self.norm_topk_prob = norm_topk_prob

        self.weight = nn.Parameter(torch.empty(n_routed_experts, hidden_size))
        self.register_buffer("e_score_correction_bias", torch.zeros(n_routed_experts))

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, hidden_states: torch.Tensor):
        bsz, seq_len, h = hidden_states.shape
        hidden_states = hidden_states.view(-1, h)

        logits = F.linear(hidden_states.float(), self.weight.float())
        scores = logits.sigmoid()

        scores_for_choice = scores + self.e_score_correction_bias.unsqueeze(0)

        group_scores = (
            scores_for_choice.view(bsz * seq_len, self.n_group, -1)
            .topk(2, dim=-1)[0]
            .sum(dim=-1)
        )
        group_idx = torch.topk(group_scores, k=self.topk_group, dim=-1, sorted=False)[1]
        group_mask = torch.zeros_like(group_scores)
        group_mask.scatter_(1, group_idx, 1)

        score_mask = (
            group_mask.unsqueeze(-1)
            .expand(bsz * seq_len, self.n_group, self.n_routed_experts // self.n_group)
            .reshape(bsz * seq_len, -1)
        )
        tmp_scores = scores_for_choice.masked_fill(~score_mask.bool(), 0.0)
        _, topk_idx = torch.topk(tmp_scores, k=self.top_k, dim=-1, sorted=False)

        topk_weight = scores.gather(1, topk_idx)

        if self.top_k > 1 and self.norm_topk_prob:
            denominator = topk_weight.sum(dim=-1, keepdim=True) + 1e-20
            topk_weight = topk_weight / denominator
        topk_weight = topk_weight * self.routed_scaling_factor

        return topk_idx, topk_weight


class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        n_shared_experts: int = 0,
        routed_scaling_factor: float = 1.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.n_routed_experts = n_routed_experts
        self.num_experts_per_tok = num_experts_per_tok
        self.n_shared_experts = n_shared_experts
        self.fused_ops = fused_ops

        self.gate_proj = nn.Parameter(
            torch.randn(n_routed_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(n_routed_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(n_routed_experts, hidden_size, intermediate_size) * 0.02
        )

        self.gate = MoEGate(
            hidden_size=hidden_size,
            n_routed_experts=n_routed_experts,
            num_experts_per_tok=num_experts_per_tok,
            n_group=n_group,
            topk_group=topk_group,
            routed_scaling_factor=routed_scaling_factor,
        )

        if n_shared_experts > 0:
            shared_intermediate = intermediate_size * n_shared_experts
            self.shared_gate_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_up_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_down_proj = nn.Linear(shared_intermediate, hidden_size, bias=False)
        else:
            self.shared_gate_proj = None

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        assert not self.training, "DeepSeek MoE grouped selection is inference-only"

        identity = hidden_states
        orig_shape = hidden_states.shape
        bsz, seq_len, _ = orig_shape

        topk_idx, topk_weight = self.gate(hidden_states)
        hidden_states = hidden_states.view(-1, self.hidden_size)
        num_tokens = hidden_states.shape[0]

        flat_topk_idx = topk_idx.view(-1)

        expanded_tokens = hidden_states.unsqueeze(1).expand(-1, self.num_experts_per_tok, -1)
        expanded_tokens = expanded_tokens.reshape(-1, self.hidden_size)

        selected_gate = self.gate_proj[flat_topk_idx]
        selected_up = self.up_proj[flat_topk_idx]
        selected_down = self.down_proj[flat_topk_idx]

        x = expanded_tokens.unsqueeze(-1)

        gate_out = torch.bmm(selected_gate, x).squeeze(-1)
        up_out = torch.bmm(selected_up, x).squeeze(-1)

        # Use fused SiLU * mul kernel
        intermediate = self.fused_ops.fused_silu_mul_hip(gate_out, up_out)

        expert_out = torch.bmm(selected_down, intermediate.unsqueeze(-1)).squeeze(-1)

        expert_out = expert_out.view(num_tokens, self.num_experts_per_tok, self.hidden_size)

        # Use fused weighted sum kernel
        y = self.fused_ops.fused_weighted_sum_hip(expert_out, topk_weight)

        y = y.view(*orig_shape)

        if self.shared_gate_proj is not None:
            shared_gate_out = self.shared_gate_proj(identity)
            shared_up_out = self.shared_up_proj(identity)
            shared_intermediate = self.fused_ops.fused_silu_mul_hip(
                shared_gate_out.view(-1), 
                shared_up_out.view(-1)
            ).view(shared_gate_out.shape)
            shared_out = self.shared_down_proj(shared_intermediate)
            y = y + shared_out

        return y

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused SiLU-multiply kernel and optimized MoE kernels
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Fused SiLU(gate) * up kernel
__global__ void fused_silu_mul_kernel(
    const float* __restrict__ gate,
    const float* __restrict__ up,
    float* __restrict__ out,
    int size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float g = gate[idx];
        float sigmoid_g = 1.0f / (1.0f + expf(-g));
        float silu_g = g * sigmoid_g;
        out[idx] = silu_g * up[idx];
    }
}

torch::Tensor fused_silu_mul_hip(torch::Tensor gate, torch::Tensor up) {
    auto size = gate.numel();
    auto out = torch::empty_like(gate);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_silu_mul_kernel<<<num_blocks, block_size>>>(
        gate.data_ptr<float>(),
        up.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}

// Scatter add kernel: out[idx] += weight * value for each token
__global__ void weighted_scatter_add_kernel(
    float* __restrict__ out,
    const float* __restrict__ expert_out,
    const float* __restrict__ weights,
    const long* __restrict__ token_indices,
    int num_items,
    int hidden_size
) {
    int item_idx = blockIdx.x;
    int h_idx = blockIdx.y * blockDim.x + threadIdx.x;

    if (item_idx < num_items && h_idx < hidden_size) {
        int token_idx = token_indices[item_idx];
        float w = weights[item_idx];
        float val = expert_out[item_idx * hidden_size + h_idx];
        atomicAdd(&out[token_idx * hidden_size + h_idx], w * val);
    }
}

void weighted_scatter_add_hip(
    torch::Tensor out,
    torch::Tensor expert_out,
    torch::Tensor weights,
    torch::Tensor token_indices
) {
    int num_items = expert_out.size(0);
    int hidden_size = expert_out.size(1);

    const int block_size = 256;
    dim3 grid(num_items, (hidden_size + block_size - 1) / block_size);

    weighted_scatter_add_kernel<<<grid, block_size>>>(
        out.data_ptr<float>(),
        expert_out.data_ptr<float>(),
        weights.data_ptr<float>(),
        token_indices.data_ptr<long>(),
        num_items,
        hidden_size
    );
}
"""

cpp_source = """
torch::Tensor fused_silu_mul_hip(torch::Tensor gate, torch::Tensor up);
void weighted_scatter_add_hip(torch::Tensor out, torch::Tensor expert_out, torch::Tensor weights, torch::Tensor token_indices);
"""

fused_ops = load_inline(
    name="fused_moe_ops_v2",
    cpp_sources=cpp_source,
    cuda_sources=hip_source,
    functions=["fused_silu_mul_hip", "weighted_scatter_add_hip"],
    verbose=True,
    extra_cuda_cflags=["-O3"],
)


class MoEGate(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        routed_scaling_factor: float = 1.0,
        norm_topk_prob: bool = True,
    ):
        super().__init__()
        self.top_k = num_experts_per_tok
        self.n_routed_experts = n_routed_experts
        self.n_group = n_group
        self.topk_group = topk_group
        self.routed_scaling_factor = routed_scaling_factor
        self.norm_topk_prob = norm_topk_prob

        self.weight = nn.Parameter(torch.empty(n_routed_experts, hidden_size))
        self.register_buffer("e_score_correction_bias", torch.zeros(n_routed_experts))

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, hidden_states: torch.Tensor):
        bsz, seq_len, h = hidden_states.shape
        hidden_states = hidden_states.view(-1, h)

        logits = F.linear(hidden_states.float(), self.weight.float())
        scores = logits.sigmoid()

        scores_for_choice = scores + self.e_score_correction_bias.unsqueeze(0)

        group_scores = (
            scores_for_choice.view(bsz * seq_len, self.n_group, -1)
            .topk(2, dim=-1)[0]
            .sum(dim=-1)
        )
        group_idx = torch.topk(group_scores, k=self.topk_group, dim=-1, sorted=False)[1]
        group_mask = torch.zeros_like(group_scores)
        group_mask.scatter_(1, group_idx, 1)

        score_mask = (
            group_mask.unsqueeze(-1)
            .expand(bsz * seq_len, self.n_group, self.n_routed_experts // self.n_group)
            .reshape(bsz * seq_len, -1)
        )
        tmp_scores = scores_for_choice.masked_fill(~score_mask.bool(), 0.0)
        _, topk_idx = torch.topk(tmp_scores, k=self.top_k, dim=-1, sorted=False)

        topk_weight = scores.gather(1, topk_idx)

        if self.top_k > 1 and self.norm_topk_prob:
            denominator = topk_weight.sum(dim=-1, keepdim=True) + 1e-20
            topk_weight = topk_weight / denominator
        topk_weight = topk_weight * self.routed_scaling_factor

        return topk_idx, topk_weight


class ModelNew(nn.Module):
    """
    Memory-efficient MoE implementation that processes tokens per expert
    instead of gathering all expert weights at once.
    """
    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        n_shared_experts: int = 0,
        routed_scaling_factor: float = 1.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.n_routed_experts = n_routed_experts
        self.num_experts_per_tok = num_experts_per_tok
        self.n_shared_experts = n_shared_experts
        self.fused_ops = fused_ops

        self.gate_proj = nn.Parameter(
            torch.randn(n_routed_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(n_routed_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(n_routed_experts, hidden_size, intermediate_size) * 0.02
        )

        self.gate = MoEGate(
            hidden_size=hidden_size,
            n_routed_experts=n_routed_experts,
            num_experts_per_tok=num_experts_per_tok,
            n_group=n_group,
            topk_group=topk_group,
            routed_scaling_factor=routed_scaling_factor,
        )

        if n_shared_experts > 0:
            shared_intermediate = intermediate_size * n_shared_experts
            self.shared_gate_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_up_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_down_proj = nn.Linear(shared_intermediate, hidden_size, bias=False)
        else:
            self.shared_gate_proj = None

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        assert not self.training, "DeepSeek MoE grouped selection is inference-only"

        identity = hidden_states
        orig_shape = hidden_states.shape
        bsz, seq_len, _ = orig_shape

        topk_idx, topk_weight = self.gate(hidden_states)
        hidden_states = hidden_states.view(-1, self.hidden_size)
        num_tokens = hidden_states.shape[0]

        # Memory-efficient expert computation: process each expert separately
        # instead of gathering all weights at once

        # Create output tensor
        y = torch.zeros(num_tokens, self.hidden_size, device=hidden_states.device, dtype=hidden_states.dtype)

        # Process each expert - gather tokens that use this expert
        for expert_id in range(self.n_routed_experts):
            # Find which token-slot pairs use this expert
            # topk_idx: (num_tokens, top_k)
            mask = (topk_idx == expert_id)  # (num_tokens, top_k)

            if not mask.any():
                continue

            # Get token indices and slot indices
            token_ids, slot_ids = torch.where(mask)

            # Get the input tokens for this expert
            expert_input = hidden_states[token_ids]  # (num_selected, hidden_size)

            # Get weights for this expert
            expert_weights = topk_weight[token_ids, slot_ids]  # (num_selected,)

            # Expert computation
            gate_out = F.linear(expert_input, self.gate_proj[expert_id])  # (num_selected, intermediate)
            up_out = F.linear(expert_input, self.up_proj[expert_id])      # (num_selected, intermediate)

            # Fused SiLU * mul
            intermediate = self.fused_ops.fused_silu_mul_hip(gate_out, up_out)

            # Down projection
            expert_out = F.linear(intermediate, self.down_proj[expert_id])  # (num_selected, hidden)

            # Weighted scatter add using custom kernel
            self.fused_ops.weighted_scatter_add_hip(y, expert_out, expert_weights, token_ids)

        y = y.view(*orig_shape)

        if self.shared_gate_proj is not None:
            shared_gate_out = self.shared_gate_proj(identity)
            shared_up_out = self.shared_up_proj(identity)
            shared_intermediate = self.fused_ops.fused_silu_mul_hip(
                shared_gate_out.contiguous().view(-1), 
                shared_up_out.contiguous().view(-1)
            ).view(shared_gate_out.shape)
            shared_out = self.shared_down_proj(shared_intermediate)
            y = y + shared_out

        return y

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Optimized HIP kernels for MoE
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Vectorized fused SiLU(gate) * up kernel with float4
__global__ void fused_silu_mul_vec4_kernel(
    const float* __restrict__ gate,
    const float* __restrict__ up,
    float* __restrict__ out,
    int size
) {
    int idx = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    if (idx + 3 < size) {
        float4 g = *reinterpret_cast<const float4*>(gate + idx);
        float4 u = *reinterpret_cast<const float4*>(up + idx);

        float4 result;
        result.x = (g.x / (1.0f + expf(-g.x))) * u.x;
        result.y = (g.y / (1.0f + expf(-g.y))) * u.y;
        result.z = (g.z / (1.0f + expf(-g.z))) * u.z;
        result.w = (g.w / (1.0f + expf(-g.w))) * u.w;

        *reinterpret_cast<float4*>(out + idx) = result;
    } else if (idx < size) {
        // Handle remainder
        for (int i = idx; i < size && i < idx + 4; i++) {
            float gv = gate[i];
            float sigmoid_g = 1.0f / (1.0f + expf(-gv));
            out[i] = gv * sigmoid_g * up[i];
        }
    }
}

// Scatter add kernel with vectorized loads where possible
__global__ void weighted_scatter_add_kernel(
    float* __restrict__ out,
    const float* __restrict__ expert_out,
    const float* __restrict__ weights,
    const long* __restrict__ token_indices,
    int num_items,
    int hidden_size
) {
    int item_idx = blockIdx.x;
    int h_idx = blockIdx.y * blockDim.x + threadIdx.x;

    if (item_idx < num_items && h_idx < hidden_size) {
        int token_idx = token_indices[item_idx];
        float w = weights[item_idx];
        float val = expert_out[item_idx * hidden_size + h_idx];
        atomicAdd(&out[token_idx * hidden_size + h_idx], w * val);
    }
}

// Vectorized scatter add with float4
__global__ void weighted_scatter_add_vec4_kernel(
    float* __restrict__ out,
    const float* __restrict__ expert_out,
    const float* __restrict__ weights,
    const long* __restrict__ token_indices,
    int num_items,
    int hidden_size
) {
    int item_idx = blockIdx.x;
    int h_idx_base = (blockIdx.y * blockDim.x + threadIdx.x) * 4;

    if (item_idx < num_items && h_idx_base + 3 < hidden_size) {
        int token_idx = token_indices[item_idx];
        float w = weights[item_idx];

        float4 val = *reinterpret_cast<const float4*>(expert_out + item_idx * hidden_size + h_idx_base);

        atomicAdd(&out[token_idx * hidden_size + h_idx_base + 0], w * val.x);
        atomicAdd(&out[token_idx * hidden_size + h_idx_base + 1], w * val.y);
        atomicAdd(&out[token_idx * hidden_size + h_idx_base + 2], w * val.z);
        atomicAdd(&out[token_idx * hidden_size + h_idx_base + 3], w * val.w);
    } else if (item_idx < num_items && h_idx_base < hidden_size) {
        int token_idx = token_indices[item_idx];
        float w = weights[item_idx];
        for (int i = h_idx_base; i < hidden_size && i < h_idx_base + 4; i++) {
            float val = expert_out[item_idx * hidden_size + i];
            atomicAdd(&out[token_idx * hidden_size + i], w * val);
        }
    }
}

torch::Tensor fused_silu_mul_hip(torch::Tensor gate, torch::Tensor up) {
    auto size = gate.numel();
    auto out = torch::empty_like(gate);

    const int block_size = 256;
    // Each thread handles 4 elements
    const int num_blocks = (size + block_size * 4 - 1) / (block_size * 4);

    fused_silu_mul_vec4_kernel<<<num_blocks, block_size>>>(
        gate.data_ptr<float>(),
        up.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}

void weighted_scatter_add_hip(
    torch::Tensor out,
    torch::Tensor expert_out,
    torch::Tensor weights,
    torch::Tensor token_indices
) {
    int num_items = expert_out.size(0);
    int hidden_size = expert_out.size(1);

    const int block_size = 256;

    // Use vectorized version if hidden_size is multiple of 4
    if (hidden_size % 4 == 0) {
        int num_vec4 = hidden_size / 4;
        dim3 grid(num_items, (num_vec4 + block_size - 1) / block_size);

